import{_ as e,o as n,c as s,a2 as a}from"./chunks/framework.hw3Av5Vn.js";const r="/llamatron/assets/instruments.DDXGNJYW.svg",o="/llamatron/assets/instrument_editor.D8Hsy66E.svg",y=JSON.parse('{"title":"Instruments","description":"","frontmatter":{},"headers":[],"relativePath":"INSTRUMENTS.md","filePath":"INSTRUMENTS.md"}'),d={name:"INSTRUMENTS.md"};function i(h,t,c,u,l,m){return n(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="instruments" tabindex="-1">Instruments <a class="header-anchor" href="#instruments" aria-label="Permalink to &quot;Instruments&quot;">​</a></h1><p>An instrument is where a track&#39;s notes go when the song plays in real time: a MIDI device and channel, or FluidSynth. This page covers the Instruments page and the instrument editor.</p><p><img src="'+r+'" alt="The Instruments page"></p><h2 id="what-an-instrument-is" tabindex="-1">What an Instrument Is <a class="header-anchor" href="#what-an-instrument-is" aria-label="Permalink to &quot;What an Instrument Is&quot;">​</a></h2><p>An instrument names a device and a channel. The device is one of this computer&#39;s MIDI output ports, with a channel on it from 1 to 16, or FluidSynth, the free software synthesizer the tracker starts by itself. Each track chooses an instrument in its track editor, and a track with none is left out of real-time playback. Two instruments may share a device and a channel, so one synthesizer can play every track, or each track can have a voice of its own.</p><p>An instrument can also choose a General MIDI sound, which FluidSynth plays and the MIDI (General MIDI) export gives the instrument&#39;s tracks. An instrument with a sound but no device is there for that export alone, and its tracks are silent in real time. When no track plays through an instrument with a device, playback doesn&#39;t start, and a dialog says why. No other export reads an instrument, since a Live set has instruments of its own.</p><h2 id="fluidsynth-instruments" tabindex="-1">FluidSynth Instruments <a class="header-anchor" href="#fluidsynth-instruments" aria-label="Permalink to &quot;FluidSynth Instruments&quot;">​</a></h2><p>An instrument whose Device is <code>*FluidSynth</code> plays through FluidSynth, as <a href="./FLUIDSYNTH">FluidSynth</a> describes. Its Channel shows <code>(auto)</code>, because each track through FluidSynth gets a channel of its own, as the MIDI (General MIDI) export assigns them: channel 10 for a drum track, where FluidSynth plays drums, and channels 1 to 16 in turn for the rest. Each clip starts by choosing the track&#39;s General MIDI sound.</p><p>Every example plays this way as it comes: its Real Time switch is on, and every track plays through a FluidSynth instrument, with a drum kit for the drum tracks, so opening an example and pressing <code>Space</code> on Arrange&#39;s corner plays it. A new set has no instruments until you add them.</p><h2 id="missing-devices" tabindex="-1">Missing Devices <a class="header-anchor" href="#missing-devices" aria-label="Permalink to &quot;Missing Devices&quot;">​</a></h2><p>When a set opens whose tracks play through an instrument that can&#39;t sound on this computer, a dialog says which: FluidSynth when it isn&#39;t installed, and each instrument whose MIDI port isn&#39;t connected, such as a set saved on another computer with <code>IAC Driver Bus 1</code>. The set keeps every device, so the set plays again wherever the device is, and the Instruments page can choose another.</p><h2 id="instruments-page" tabindex="-1">Instruments Page <a class="header-anchor" href="#instruments-page" aria-label="Permalink to &quot;Instruments Page&quot;">​</a></h2><p>Press <code>I</code> on the main screen to open the Instruments page. The list shows each instrument&#39;s device and channel, and how many tracks play through it. Adding the first instrument turns the main screen&#39;s Real Time switch on, and deleting the last turns it off.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>A</code></td><td>Adds an instrument with no device yet, named <code>instrument 1</code> and so on, and opens it.</td></tr><tr><td><code>Enter</code></td><td>Opens the instrument.</td></tr><tr><td><code>C</code></td><td>Copies the instrument to the end of the list.</td></tr><tr><td><code>N</code></td><td>Renames the instrument, updating every track that chose it.</td></tr><tr><td><code>M</code></td><td>Picks the instrument up: <code>↑↓</code> carry it, and <code>Enter</code> drops it.</td></tr><tr><td><code>S</code></td><td>Sorts the instruments by name.</td></tr><tr><td><code>Bksp</code></td><td>Deletes the instrument, once no track uses it.</td></tr></tbody></table><h2 id="instrument-editor" tabindex="-1">Instrument Editor <a class="header-anchor" href="#instrument-editor" aria-label="Permalink to &quot;Instrument Editor&quot;">​</a></h2><p><img src="'+o+'" alt="An instrument&#39;s settings, playing through FluidSynth"></p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>Enter</code> renames the instrument.</td></tr><tr><td>Device</td><td>The MIDI output port, chosen with <code>Enter</code> from <code>(none)</code>, then <code>*FluidSynth</code>, then the ports this computer has now, sorted. A port the set names that has disconnected is still offered, so that the set opens without the port and keeps it. <code>Bksp</code> sets none.</td></tr><tr><td>Channel</td><td>1 to 16, as the device numbers them. <code>[</code> and <code>]</code> step it, and <code>Enter</code> types it. With <code>*FluidSynth</code> it shows <code>(auto)</code> and can&#39;t be changed, since each track gets its own channel.</td></tr><tr><td>GM sound</td><td>One of General MIDI&#39;s 128 sounds, or <code>(none)</code>. <code>Enter</code> opens a picker of General MIDI&#39;s sixteen families, two to a page, with <code>(none)</code> above them, where <code>Tab</code> and <code>Shift+Tab</code> turn the pages; <code>[</code> and <code>]</code> step through the sounds by number, and <code>Bksp</code> sets none. A drum track always plays channel 10&#39;s drum kit.</td></tr></tbody></table>',17)])])}const I=e(d,[["render",i]]);export{y as __pageData,I as default};
